head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.key_isur_cd = '';
scwin.key_chrg_tp_cd = '';
scwin.key_seq = '';
scwin.key_assgn_dd = '';
scwin.gDepCd = js_dep_cd;
scwin.gLdMktTp = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // fn_HideDebugCtrls();
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        scwin.init();
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        if (scwin.gLdMktTp === '1') {
            // 유가시에만 공시담당자1,공시담당자2 --> 공시담당자(정),공시담당자(부)로 변경
            let tmp = grd_List.Format;
            tmp = tmp.replace("공시담당자1", "공시담당자(정)");
            tmp = tmp.replace("공시담당자2", "공시담당자(부)");
            grd_List.Format = tmp;
        }
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30614.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    rdo_MARKET_FLAG.setValue(js_market);
    if (js_market !== "9") {
        panel_mkt.hide();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function() {
    try {
        scwin.gDepCd = cmb_DEP_CD.getValue(); // ;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

        dts_EMP_NO.UseFilter = true;
        dts_EMP_NO.Filter();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30614.cmb_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnFilter
 * @description EMP NO On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnFilter = function(row) {
    try {
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_EMP_NO.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_EMP_NO.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30614.dts_EMP_NO_OnFilter" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30614.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        // if (rowcount > 0)
        //    grd_List.AutoResizeAllCol(true);
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        // alert(rowcount);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30614.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30614.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF30614.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_List, {fileName: "정보등록현황", type: "2"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30614.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30614.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30614.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30614.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30614.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30614.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30614.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30614.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30614.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30614.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30614.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        if (colid === 'DETAIL') {
            await scwin.openDetailInfo(dts_Grid.getCellData(row, "ISUR_CD"), dts_Grid.getCellData(row, "CHRG_TP_CD"), dts_Grid.getCellData(row, "SEQ"), dts_Grid.getCellData(row, "DISCLS_BZ_CHRG_ASSGN_DD"));
        } else if (colid === 'REMK') {
            const acpt_no = dts_Grid.getCellData(row, "ACPT_NO");
            if (acpt_no !== '') {
                await $c.stf.openDisclViewer(dts_Grid.getCellData(row, "ACPT_NO"), "R"); // (정정)공시일 컬럼 더블클릭시 관련 보고서 뷰잉

            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30614.grd_List_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_EMP_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&MKT_ID=" + rdo_MARKET_FLAG.getValue();
    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&DEP_CD=" + cmb_DEP_CD.getValue();
    url += "&EMP_NO=" + cmb_EMP_NO.getValue();
    url += "&CHRG_TP_CD=" + cmb_CHRG_TP_CD.getValue();
    url += "&LST_HIST_YN=" + chk_LST_HIST_YN.getValue();
    url += "&SCREN_ID=" + "ULDSTF30614.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openDetailInfo
 * @description open Detail Info 처리
 * @param {*} isur_cd isur_cd
 * @param {*} chrg_tp_cd chrg_tp_cd
 * @param {*} seq seq
 * @param {*} assgn_dd assgn_dd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailInfo = async function(isur_cd, chrg_tp_cd, seq, assgn_dd) {
    scwin.key_isur_cd = isur_cd;
    scwin.key_chrg_tp_cd = chrg_tp_cd;
    scwin.key_seq = seq;
    scwin.key_assgn_dd = assgn_dd;
    await $c.frame.CreateFrame("child01", "/issueinfo/ULDSTF30615.gfm", "상세보기", 10, 10, 770, 610, "window", 0, 0, true);
};
